/**
 * @brief Draw card at position x,y
 * @param x Horizontal card position (0-31)
 * @param y Vertical card position (0-23)
 * @param partial enum (see ../platform-specific/graphics.h)
 * @param s String indicating number and suit. (e.g. "as" for ace of spades)
 * @param isHidden is card currently overturned?
 */
void drawCard(unsigned char x, unsigned char y, unsigned char partial, const char* s, unsigned char isHidden)
{
    unsigned char val, suit, suitTile, rankBase, i;

    if (x==WIDTH-3 && s[0]!='?' && peek(x,y+1)==UDG_BACK_L_TOP) {
        drawCard(x+1,y,PARTIAL_RIGHT,"??",false);
    }

    if (partial == PARTIAL_LEFT)
    {
        put(x, y++, UDG_CARD_TL, T_CARD_TL_RG);
        put(x, y++, UDG_BACK_L_TOP, T_BACK_L_TOP_RW);
        put(x, y++, UDG_BACK_L_MID, T_BACK_L_MID_RW);
        put(x, y++, UDG_BACK_L_BOT, T_BACK_L_BOT_RW);
        put(x, y++, UDG_CARD_BL, T_CARD_BL_RG);
    }
    else if (partial == PARTIAL_RIGHT)
    {
        x++;
        put(x, y++, UDG_CARD_TOP_TRIM, T_CARD_TOP_TRIM_RG);
        put(x, y++, UDG_BACK_RCOL_TOP, T_BACK_RCOL_TOP_RW);
        put(x, y++, UDG_BACK_RCOL_MID, T_BACK_RCOL_MID_RW);
        put(x, y++, UDG_BACK_RCOL_BOT, T_BACK_RCOL_BOT_RW);
        put(x, y++, UDG_CARD_BOT_TRIM, T_CARD_BOT_TRIM_RG);
    }
    else // FULL CARD
    {
        // A hidden hole card is greyed, rather than banded, where it can be.
        shadeCard(x, y, isHidden && s[0] != '?');

        switch (s[1])
        {
        case 'h' :
            suit=UDG_SUIT_HEART;
            suitTile=T_SUIT_HEART_RW;
            rankBase=T_RANK_RW;
            break;
        case 'd' :
            suit=UDG_SUIT_DIAMOND;
            suitTile=T_SUIT_DIAMOND_RW;
            rankBase=T_RANK_RW;
            break;
        case 'c' :
            suit=UDG_SUIT_CLUB;
            suitTile=T_SUIT_CLUB_KW;
            rankBase=T_RANK_KW;
            break;
        case 's' :
            suit=UDG_SUIT_SPADE;
            suitTile=T_SUIT_SPADE_KW;
            rankBase=T_RANK_KW;
            break;
        default:
            suit=UDG_CARD_VERT;         // Something wrong.
            suitTile=T_CARD_VERT_RW;
            rankBase=T_RANK_RW;
            break;
        }

        // If card is overturned, draw the back
        if (s[0]=='?')
        {
            // Shift right card left one for easy drawing of border
            // As well as clear existing cards, assuming a fold
            if (x>WIDTH-3) {
                for (i=0;i<5;i++)
                    putText(x-7,y+i,"      ",T_TEXT);
                x--;
            } else {
                for (i=0;i<5;i++)
                    putText(x+3,y+i,"       ",T_TEXT);
            }
            put(x, y, UDG_CARD_TL, T_CARD_TL_RG);
            put(x+1, y, UDG_CARD_TOP, T_CARD_TOP_RG);
            put(x+2, y, UDG_CARD_TR_STUB, T_CARD_TR_STUB_RG);
            y++;
            put(x, y, UDG_BACK_L_TOP, T_BACK_L_TOP_RW);
            put(x+1, y, UDG_BACK_R_TOP, T_BACK_R_TOP_RW);
            put(x+2, y, UDG_CARD_VERT, T_CARD_VERT_RG);
            y++;
            put(x, y, UDG_BACK_L_MID, T_BACK_L_MID_RW);
            put(x+1, y, UDG_BACK_R_MID, T_BACK_R_MID_RW);
            put(x+2, y, UDG_CARD_VERT, T_CARD_VERT_RG);
            y++;
            put(x, y, UDG_BACK_L_BOT, T_BACK_L_BOT_RW);
            put(x+1, y, UDG_BACK_R_BOT, T_BACK_R_BOT_RW);
            put(x+2, y, UDG_CARD_VERT, T_CARD_VERT_RG);
            y++;
            put(x, y, UDG_CARD_BL, T_CARD_BL_RG);
            put(x+1, y, UDG_CARD_BOT, T_CARD_BOT_RG);
            put(x+2, y, UDG_CARD_BR_STUB, T_CARD_BR_STUB_RG);
        }
        else // Draw the full card.
        {
            // Top card border
            if (peek(x+1,y)!=UDG_CARD_TOP)
            {
                put(x, y, UDG_CARD_TL, T_CARD_TL_RG);
                put(x+1, y, UDG_CARD_TOP, T_CARD_TOP_RG);
            }
            if (peek(x+2,y)==' ')
                put(x+2, y, UDG_CARD_TR_STUB, T_CARD_TR_STUB_RG);

            switch (s[0])
            {
            case 't':
                val=UDG_RANK_T; // 10
                break;
            case 'j':
                val=UDG_RANK_J;
                break;
            case 'q':
                val=UDG_RANK_Q;
                break;
            case 'k':
                val=UDG_RANK_K;
                break;
            case 'a':
                val=UDG_RANK_A;
                break;
            default:
                val=UDG_RANK_2+(s[0]-'2');
                break;
            }

            // Left border and card value
            y++;
            put(x, y, UDG_CARD_VERT, T_CARD_VERT_RW);
            put(x+1, y, val, rankBase + (val - UDG_RANK_2));
            if (peek(x+2,y)==' ')
                put(x+2, y, UDG_CARD_VERT, T_CARD_VERT_RG);

            // Interior (hole-card marker band if hidden)
            y++;
            if (isHidden && (x & 1))
            {
                put(x, y, UDG_HIDDEN_L, T_HIDDEN_L_RW);
                put(x+1, y, UDG_HIDDEN_R, T_HIDDEN_R_RW);
            }
            else
            {
                put(x, y, UDG_CARD_VERT, T_CARD_VERT_RW);
                put(x+1, y, ' ', T_BLANK_W);
            }
            if (peek(x+2,y)==' ')
                put(x+2, y, UDG_CARD_VERT, T_CARD_VERT_RG);

            // Suit
            y++;
            put(x, y, UDG_CARD_VERT, T_CARD_VERT_RW);
            put(x+1, y, suit, suitTile);
            if (peek(x+2,y)==' ')
                put(x+2, y, UDG_CARD_VERT, T_CARD_VERT_RG);

            // Bottom border
            y++;
            if (peek(x+1,y)!=UDG_CARD_BOT)
            {
                put(x, y, UDG_CARD_BL, T_CARD_BL_RG);
                put(x+1, y, UDG_CARD_BOT, T_CARD_BOT_RG);
            }
            if (peek(x+2,y)==' ')
                put(x+2, y, UDG_CARD_BR_STUB, T_CARD_BR_STUB_RG);
        }
    }
}

/* Up to n characters of s on the status bar, white on black. */
static void putStatus(unsigned char x, unsigned char y, const char *s, unsigned char n)
{
    unsigned char c;

    while (n-- && (c = (unsigned char) *s++) != 0 && x < WIDTH)
    {
        c = textGlyph(c);
        put(x++, y, c, T_STATUS + (c - 0x20));
    }
}

/* A message too long for one row (the round result) takes row 22 into the
   bar as well, word-wrapped across the two. */
void drawStatusTextAt(unsigned char x, const char* s)
{
    unsigned char brk, i;

    if (strlen(s) <= WIDTH)
    {
        putStatus(x, STATUS_ROW, s, WIDTH);
        return;
    }

    for (brk = WIDTH; brk > 0 && s[brk] != ' '; brk--) ;
    if (brk == 0)
        brk = WIDTH;

    tallStatus = true;
    for (i = 0; i < WIDTH; i++)
    {
        put(i, 22, ' ', T_STATUS);
        put(i, STATUS_ROW, ' ', T_STATUS);
    }
    putStatus(0, 22, s, brk);
    putStatus(0, STATUS_ROW, s + brk + (s[brk] == ' '), WIDTH);
}

void drawStatusText(const char* s)
{
    clearStatusBar();
    drawStatusTextAt(0, s);
}

