/* The highlighted or plain tile for what a cell shows: a red underline on the
   status row (the move under the cursor), a red bar across the top of the row
   under the active player's name elsewhere -- blank cells, or the tops of that
   player's cards. Cells with no highlight variant are left alone. */
static unsigned char lineTile(unsigned char g, unsigned char y, bool on)
{
    if (y == STATUS_ROW)
    {
        if (g < 0x20 || g > 0x5F)
            return NO_TILE;
        if (!on)
            return T_STATUS + (g - 0x20);
        if (g == ' ')
            return T_STATUS_UL;
        if (g >= '0' && g <= '9')
            return T_STATUS_UL + 1 + (g - '0');
        if (g >= 'A' && g <= 'Z')
            return T_STATUS_UL + 11 + (g - 'A');
        return NO_TILE;
    }
    switch (g)
    {
    case ' ':               return on ? T_TOPBAR_SPACE : T_TEXT;
    case UDG_CARD_TL:       return on ? T_TOPBAR_CARD_TL : T_CARD_TL_RG;
    case UDG_CARD_TOP:      return on ? T_TOPBAR_CARD_TOP : T_CARD_TOP_RG;
    case UDG_CARD_TR_STUB:  return on ? T_TOPBAR_CARD_TR_STUB : T_CARD_TR_STUB_RG;
    case UDG_CARD_TOP_TRIM: return on ? T_TOPBAR_CARD_TOP_TRIM : T_CARD_TOP_TRIM_RG;
    }
    return NO_TILE;
}

static void line(unsigned char x, unsigned char y, unsigned char w, bool on)
{
    unsigned char t;

    if (y >= HEIGHT)
        return;
    for (; w != 0 && x < WIDTH; w--, x++)
    {
        t = lineTile(shadow[y][x], y, on);
        if (t != NO_TILE)
            ppu_put(NT_BASE + ((unsigned int)(y + ROW0) << 5) + x, t);
    }
}

void hideLine(unsigned char x, unsigned char y, unsigned char w)
{
    line(x, y, w, false);
}

void drawLine(unsigned char x, unsigned char y, unsigned char w)
{
    line(x, y, w, true);
}

